  while (pos < input.length && input.charCodeAt(pos) <= 32) pos++;
  let value = 0;
  while (pos < input.length) {
    const c = input.charCodeAt(pos);
    if (c <= 32) break;
    value = value * 10 + c - 48;
    pos++;
  }
  return value;
}

const N = nextInt();
const M = nextInt();
const K = nextInt();

const price = new Int32Array(K);
for (let i = 0; i < K; i++) price[i] = nextInt();

const maxMemberships = 2 * M;
const parent = new Int32Array(maxMemberships);
const rank = new Uint8Array(maxMemberships);
const stationOf = [];
const colorOf = [];
const membershipMap = new Map();
let membershipCount = 0;

function getMembership(station, color) {
  const key = (color - 1) * (N + 1) + station;
  let id = membershipMap.get(key);
  if (id === undefined) {
    id = membershipCount++;
    membershipMap.set(key, id);
    parent[id] = id;
    stationOf.push(station - 1);
    colorOf.push(color - 1);
  }
  return id;
}

function find(x) {
  let root = x;
  while (parent[root] !== root) root = parent[root];
  while (parent[x] !== x) {
    const next = parent[x];
    parent[x] = root;
    x = next;
  }
  return root;
}

function unite(a, b) {
  let ra = find(a);
  let rb = find(b);
  if (ra === rb) return;
  if (rank[ra] < rank[rb]) {
    const temp = ra;
    ra = rb;
    rb = temp;
  }
  parent[rb] = ra;
  if (rank[ra] === rank[rb]) rank[ra]++;
}

for (let i = 0; i < M; i++) {
  const v = nextInt();
  const u = nextInt();
  const t = nextInt();
  unite(getMembership(v, t), getMembership(u, t));
}

const A = nextInt() - 1;
const B = nextInt() - 1;

const nodeCount = N + membershipCount;
const head = new Int32Array(nodeCount);
head.fill(-1);

const edgeCapacity = 2 * membershipCount;
const to = new Int32Array(edgeCapacity);
const next = new Int32Array(edgeCapacity);
const weight = new Uint16Array(edgeCapacity);
let edgeCount = 0;

function addEdge(from, dest, cost) {
  to[edgeCount] = dest;
  weight[edgeCount] = cost;
  next[edgeCount] = head[from];
  head[from] = edgeCount++;
}

for (let id = 0; id < membershipCount; id++) {
  const station = stationOf[id];
  const componentNode = N + find(id);
  addEdge(station, componentNode, price[colorOf[id]]);
  addEdge(componentNode, station, 0);
}

const dist = new Float64Array(nodeCount);
dist.fill(Infinity);
dist[A] = 0;

const heapNode = [];
const heapDist = [];
let heapSize = 0;
let poppedDist = 0;

function push(node, distance) {
  let i = heapSize++;
  while (i > 0) {
    const p = (i - 1) >> 1;
    if (heapDist[p] <= distance) break;
    heapNode[i] = heapNode[p];
    heapDist[i] = heapDist[p];
    i = p;
  }
  heapNode[i] = node;
  heapDist[i] = distance;
}

function pop() {
  const resultNode = heapNode[0];
  poppedDist = heapDist[0];

  const lastNode = heapNode[--heapSize];
  const lastDist = heapDist[heapSize];

  if (heapSize > 0) {
    let i = 0;
    while (true) {
      let child = i * 2 + 1;
      if (child >= heapSize) break;
      if (child + 1 < heapSize && heapDist[child + 1] < heapDist[child]) child++;
      if (heapDist[child] >= lastDist) break;
      heapNode[i] = heapNode[child];
      heapDist[i] = heapDist[child];
      i = child;
    }
    heapNode[i] = lastNode;
    heapDist[i] = lastDist;
  }

  return resultNode;
}

push(A, 0);

while (heapSize > 0) {
  const node = pop();
  const currentDist = poppedDist;
  if (currentDist !== dist[node]) continue;
  if (node === B) break;

  for (let e = head[node]; e !== -1; e = next[e]) {
    const neighbor = to[e];
    const newDist = currentDist + weight[e];
    if (newDist < dist[neighbor]) {
      dist[neighbor] = newDist;
      push(neighbor, newDist);
    }
  }
}

